/* Plain-language notes for transfer-pricing jargon that appears in case dialogue and choices. */
(function (root) {
const TERMS = [
  ['口徑', '計算時採用的範圍與基準，例如哪些成本、哪些年度、哪家公司算進來'],
  ['一致口徑', '比較的兩邊用同一套範圍與基準，數字才能互相比'],
  ['橋接', '把財報數字一步步對到申報或測試用的數字，每一步都說得出來源'],
  ['移轉包', '集團重組時一起被移走的功能、資產、風險、合約與人員'],
  ['FAR', '功能（Function）、資產（Asset）、風險（Risk）分析：誰做事、誰出資產、誰扛風險'],
  ['DEMPE', '無形資產的開發、提升、維護、保護、利用：看誰真正做了這五件事'],
  ['TNMM', '交易淨利率法：拿受測公司的營業利潤率和可比公司比'],
  ['LRD', '有限風險經銷商：只做買賣，市場與存貨風險多由集團承擔，賺穩定但不高的利潤'],
  ['有限風險', '主要風險由別的集團公司承擔，所以報酬穩定、較低'],
  ['受測個體', '在 TNMM 裡被拿來和可比公司比利潤率的那一方，通常是功能較單純的一方'],
  ['例行報酬', '一般外包商做同樣的事就會賺到的普通利潤，不含無形資產的超額報酬'],
  ['剩餘利潤', '扣掉各方例行報酬後，剩下要按貢獻分的超額利潤'],
  ['利潤分割', '雙方都有獨特貢獻時，把合併利潤按貢獻比例切開的方法'],
  ['可比', '條件夠相近、能拿來當市場行情參考的獨立交易或公司'],
  ['常規交易', '獨立企業之間在相同情況下會接受的交易條件（arm’s length）'],
  ['獨立企業', '彼此沒有控制關係、各自為自己利益談價格的公司'],
  ['關係人', '同一集團或有控制關係的公司，彼此交易的價格要受移轉訂價檢驗'],
  ['加成', '在成本上再加一定比例當作利潤'],
  ['成本基礎', '計算加成時當作分母的成本，算進哪些成本會直接改變利潤'],
  ['分母', '計算利潤率時被除的那個數，例如成本或營收'],
  ['轉手', '只是經手付款，沒有加工、選擇或承擔風險'],
  ['pass-through', '代墊轉手成本：只經手不增值，通常不加成'],
  ['控制風險', '有能力也實際去決定要不要承擔風險、如何因應的人'],
  ['財務能力', '風險真的發生時，付得起損失的能力'],
  ['風險承擔', '合約說誰扛只是起點，還要看誰控制、誰付得起'],
  ['法律所有權', '登記或合約上的擁有者；只有法律所有權不一定能拿走全部無形資產報酬'],
  ['無形資產', '專利、配方、商標、客戶關係等看不見但能賺錢的東西'],
  ['權利金', '使用別人的無形資產所付的費用'],
  ['綜效', '因為身在集團而自然得到的好處；被動得到的不一定要付費'],
  ['集團綜效', '集團規模帶來的議價力或便利；被動得到的通常不另外計價'],
  ['估值', '估算一項資產或業務值多少錢，常用未來現金流折現'],
  ['事前', '交易當時能知道的資訊；不能拿事後結果回頭改定價'],
  ['對應調整', '一國調高所得後，另一國相應調低，避免同一筆利潤被兩國課稅'],
  ['MAP', '相互協議程序：兩國主管機關協商解決重複課稅'],
  ['功能分析', '把誰做了什麼、用了什麼資產、扛了什麼風險逐項列清楚'],
  ['TPG', 'OECD 移轉訂價指南，各國查核與協商共同參考的國際文件'],
  ['毛利', '營收減銷貨成本，還沒扣營業費用'],
  ['營業利益', '毛利再扣營業費用後的利潤，TNMM 常用它算利潤率']
].sort((a, b) => b[0].length - a[0].length);

function find(text, limit = 3) {
  const s = String(text || ''), hits = [], taken = [];
  for (const [term, note] of TERMS) {
    const at = s.indexOf(term);
    if (at < 0 || taken.some(([a, b]) => at < b && at + term.length > a)) continue;
    taken.push([at, at + term.length]);
    hits.push({ term, note, at });
  }
  return hits.sort((a, b) => a.at - b.at).slice(0, limit);
}

const api = { TERMS, find };
if (typeof module !== 'undefined') module.exports = api;
root.TPGlossary = api;
})(typeof window !== 'undefined' ? window : globalThis);
